package com.unicare.dispensary.screening;import jakarta.validation.constraints.*;import java.time.LocalDate;public record ScreeningRequest(@NotNull @PastOrPresent LocalDate date,@Size(max=300)String allergies,@Size(max=500)String conditions,@Size(max=500)String currentMedication,@NotBlank @Pattern(regexp="Good|Fair|Poor")String wellbeing,@Size(max=1000)String symptoms,@Size(max=1000)String notes,@AssertTrue boolean consent){}
